<template>
  <div class="hh-page hh-detail-page">
    <router-link to="/hospitalizacion/estaciones" class="hh-back-link d-inline-flex align-items-center mb-3"><i class="ri-arrow-left-line me-1"></i>Volver a estaciones</router-link>
    <div v-if="loading" class="text-center py-5"><span class="spinner-border text-primary"></span><p class="text-muted mt-2">Actualizando estación…</p></div>
    <div v-else-if="error" class="alert alert-danger"><strong>No fue posible consultar la estación.</strong> {{ error }}<button class="btn btn-sm btn-outline-danger ms-3" @click="load">Reintentar</button></div>
    <template v-else-if="detail">
      <div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><p class="text-primary fw-semibold mb-1">Estación #{{ detail.estacion?.id }}</p><h2 class="mb-1">{{ detail.estacion?.nombre }}</h2><p class="text-muted mb-0">Distribución de salas, habitaciones, camas y pacientes activos.</p></div><div class="d-flex gap-2"><router-link :to="`/hospitalizacion/estaciones/${route.params.id}/reservas`" class="btn btn-primary"><i class="ph ph-bell me-1"></i>Reservas</router-link><button class="btn btn-outline-primary" @click="load"><i class="ri-refresh-line me-1"></i>Actualizar</button></div></div><div v-if="actionMessage" class="alert" :class="`alert-${actionMessageType}`">{{ actionMessage }}</div>
      <div class="row g-3 mb-4"><div v-for="metric in metrics" :key="metric.label" class="col-6 col-md-4 col-xl"><div class="metric"><small>{{ metric.label }}</small><strong :class="metric.class">{{ metric.value }}</strong></div></div></div>
      <div v-if="!detail.salas?.length" class="card card-body text-center py-5 text-muted">Esta estación no tiene salas registradas.</div>
      <b-card v-for="room in detail.salas" v-else :key="room.id_sala" no-body class="mb-4"><b-card-header class="d-flex flex-wrap justify-content-between align-items-center gap-2"><div><h4 class="mb-0">{{ room.nombre_sala }}</h4><small class="text-muted">{{ room.tipo_sala?.nombre }}</small></div><span class="badge bg-primary-subtle text-primary">{{ room.resumen?.total_camas }} camas</span></b-card-header><b-card-body>
        <div v-for="bedroom in room.habitaciones" :key="bedroom.id_habitacion" class="bedroom mb-4"><div class="d-flex justify-content-between mb-3"><h5 class="mb-0"><i class="ri-door-open-line me-2 text-primary"></i>{{ bedroom.nombre_habitacion }}</h5><small>{{ bedroom.resumen?.ocupadas }} ocupadas · {{ bedroom.resumen?.disponibles }} disponibles</small></div>
          <div class="row g-3"><div v-for="bed in bedroom.camas" :key="bed.id_cama" class="col-md-6 col-xxl-4"><article class="bed" :class="bed.info_paciente ? 'occupied' : bed.disponibilidad ? 'available' : 'unavailable'"><header class="bed-header"><div><i class="ph ph-bed me-2"></i><strong>{{ bed.nombre }}</strong></div><span class="status"><i class="ph ph-circle-fill"></i>{{ bed.info_paciente ? 'Ocupada' : bed.disponibilidad ? 'Disponible' : bed.estado_uso?.nombre || 'No disponible' }}</span></header>
            <template v-if="bed.info_paciente"><div v-if="bed.info_paciente.signos_vitales?.ultimo?.tiene_alertas" class="clinical-alert" role="alert"><i class="ph ph-warning"></i><strong>Alerta en últimos signos vitales</strong></div><div class="patient"><div class="patient-avatar">{{ initials(bed.info_paciente.nombre) }}</div><div><strong>{{ bed.info_paciente.nombre }}</strong><small>{{ bed.info_paciente.identificacion }}</small><span>{{ bed.info_paciente.hospitalizacion?.servicio || 'Servicio hospitalario' }}</span></div></div><div class="stay-summary"><div><small>Ingreso</small><strong>{{ formatDate(bed.info_paciente.hospitalizacion?.fecha_ingreso) }}</strong></div><div><small>Estancia</small><strong>{{ bed.info_paciente.hospitalizacion?.dias_hospitalizado ?? 0 }} días</strong></div></div>
              <div class="clinical-summary"><div><i class="ph ph-heartbeat"></i><span><small>Últimos signos</small><strong v-if="bed.info_paciente.signos_vitales?.ultimo">{{ vitalSummary(bed.info_paciente.signos_vitales.ultimo) }}</strong><strong v-else>Sin registros</strong></span></div><div><i class="ph ph-pill"></i><span><small>Medicamentos</small><strong>{{ bed.info_paciente.plan_medicamentos ? 'Plan activo' : 'Sin plan activo' }}</strong></span></div><div><i class="ph ph-clipboard-text"></i><span><small>Procedimientos</small><strong v-if="bed.info_paciente.plan_procedimientos">{{ bed.info_paciente.plan_procedimientos.pendientes || 0 }} pendientes · {{ bed.info_paciente.plan_procedimientos.realizados || 0 }} realizados</strong><strong v-else>Sin plan activo</strong></span></div></div>
              <div v-if="bed.info_paciente.hospitalizacion?.responsable" class="responsible"><i class="ph ph-stethoscope"></i><span><small>Profesional responsable</small><strong>{{ bed.info_paciente.hospitalizacion.responsable.name }}</strong></span></div>
              <div class="bed-actions">
                <router-link :to="attentionRoute(bed)" target="_blank" rel="noopener noreferrer" class="btn btn-primary flex-grow-1"><i class="ph ph-first-aid me-1"></i>Abrir atención <i class="ph ph-arrow-square-out ms-1"></i></router-link>
                <details class="action-menu">
                  <summary class="btn btn-outline-primary" :aria-label="`Acciones para ${bed.info_paciente.nombre}`"><i class="ph ph-dots-three-vertical"></i></summary>
                  <div class="action-menu-list">
                    <span>Consultas</span>
                    <router-link :to="`/pacientes/${bed.info_paciente.id_paciente}`" target="_blank" rel="noopener noreferrer"><i class="ph ph-user"></i>Ver paciente<i class="ph ph-arrow-square-out external-icon"></i></router-link>
                    <router-link v-if="bed.info_paciente.hospitalizacion?.id" :to="`/hospitalizacion/${bed.info_paciente.hospitalizacion.id}`" target="_blank" rel="noopener noreferrer"><i class="ph ph-buildings"></i>Ver hospitalización<i class="ph ph-arrow-square-out external-icon"></i></router-link>
                    <router-link v-if="bed.info_paciente.hospitalizacion?.id_orden_trabajo" :to="`/admisiones/${bed.info_paciente.hospitalizacion.id_orden_trabajo}`" target="_blank" rel="noopener noreferrer"><i class="ph ph-file-text"></i>Ver orden de trabajo<i class="ph ph-arrow-square-out external-icon"></i></router-link>
                    <button @click="openVitals(bed)"><i class="ph ph-heartbeat"></i>Signos vitales</button>
                    <button @click="openBedPlan(bed, 'medication')"><i class="ph ph-pill"></i>Medicamentos</button>
                    <button @click="openBedPlan(bed, 'procedure')"><i class="ph ph-clipboard-text"></i>Procedimientos</button>
                    <router-link :to="{ ...attentionRoute(bed), hash: '#historia-clinica' }" target="_blank" rel="noopener noreferrer"><i class="ph ph-book-open-text"></i>Historia clínica<i class="ph ph-arrow-square-out external-icon"></i></router-link>
                    <span>Gestión</span>
                    <button v-if="bed.info_paciente.hospitalizacion?.estado !== 'en_traslado'" @click="openTransfer(bed)"><i class="ph ph-arrows-left-right"></i>Solicitar traslado</button>
                    <router-link v-if="bed.info_paciente.hospitalizacion?.id" class="danger-action" :to="{ ...attentionRoute(bed), hash: '#egreso' }" target="_blank" rel="noopener noreferrer"><i class="ph ph-sign-out"></i>Egresar paciente<i class="ph ph-arrow-square-out external-icon"></i></router-link>
                  </div>
                </details>
              </div>
            </template><div v-else class="empty-bed"><i class="ph ph-bed"></i><span>Sin paciente asignado</span></div><div v-if="bed.reservas_activas" class="reservation"><i class="ph ph-calendar-check me-1"></i>{{ bed.reservas_activas }} {{ bed.reservas_activas === 1 ? 'reserva activa' : 'reservas activas' }}</div></article></div></div>
        </div>
      </b-card-body></b-card>
    </template>
    <SignosVitalesModal v-if="vitalsPatient" :patient="vitalsPatient" @close="vitalsPatient = null" />
    <PlanActivoModal v-if="viewerType" :type="viewerType" :context="planContext" :patient-name="selectedBed?.info_paciente?.nombre" :plan="viewerType === 'medication' ? plans.medicationPlan : plans.procedurePlan" @close="closePlan" @create="createPlan" />
    <PlanClinicoModal v-if="editorType" :type="editorType" :context="planContext" :patient-name="selectedBed?.info_paciente?.nombre" :active-plan="editorType === 'medication' ? plans.medicationPlan : plans.procedurePlan" @close="closePlan" @saved="planSaved" />
    <SolicitarTrasladoModal v-if="transferBed" :bed="transferBed" @close="transferBed = null" @saved="transferSaved" />
  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { obtenerMensajeError } from '@/services/api'
import { useStationsStore } from '@/store/pinia/estaciones'
import { usePatientPlansStore } from '@/store/pinia/planesPaciente'
import SignosVitalesModal from '@/views/clinical/SignosVitalesModal.vue'
import PlanActivoModal from '@/views/clinical/PlanActivoModal.vue'
import PlanClinicoModal from '@/views/clinical/PlanClinicoModal.vue'
import SolicitarTrasladoModal from '@/views/clinical/SolicitarTrasladoModal.vue'
const route = useRoute(), store = useStationsStore(), plans = usePatientPlansStore(), detail = ref(null), loading = ref(true), error = ref(''), vitalsPatient = ref(null), selectedBed = ref(null), viewerType = ref(null), editorType = ref(null), transferBed = ref(null), actionMessage = ref(''), actionMessageType = ref('danger')
const metrics = computed(() => { const r = detail.value?.resumen || {}; return [{ label: 'Salas', value: r.total_salas ?? 0 }, { label: 'Habitaciones', value: r.total_habitaciones ?? 0 }, { label: 'Camas', value: r.total_camas ?? 0 }, { label: 'Ocupadas', value: r.ocupadas ?? 0, class: 'text-primary' }, { label: 'Disponibles', value: r.disponibles ?? 0, class: 'text-success' }, { label: 'Camas con reserva activa', value: r.reservadas ?? 0, class: 'text-warning' }] })
const initials = name => String(name || 'P').split(' ').slice(0, 2).map(value => value[0]).join('').toUpperCase()
const formatDate = value => value ? new Intl.DateTimeFormat('es-CO', { dateStyle: 'medium' }).format(new Date(value)) : 'No registrada'
const vitalSummary = vital => [vital.presion_arterial?.texto, vital.frecuencia_cardiaca ? `${vital.frecuencia_cardiaca} lpm` : null, vital.saturacion_oxigeno ? `${vital.saturacion_oxigeno}% SpO₂` : null].filter(Boolean).join(' · ')
function attentionRoute(bed) { const patient = bed.info_paciente, hospitalization = patient.hospitalizacion || {}; return { path: `/hospitalizacion/pacientes/${patient.id_paciente}/atencion`, query: { hospitalizacion: hospitalization.id, orden: hospitalization.id_orden_trabajo, ordenServicio: hospitalization.id_osa_hospitalizacion, cama: bed.id_cama, estacion: route.params.id } } }
function planRoute(bed, plan) { const target = attentionRoute(bed); return { ...target, query: { ...target.query, plan } } }
const planContext = computed(() => { const patient = selectedBed.value?.info_paciente, hospitalization = patient?.hospitalizacion || {}; return { patientId: Number(patient?.id_paciente), hospitalizationId: Number(hospitalization.id), workOrderId: Number(hospitalization.id_orden_trabajo), serviceOrderId: Number(hospitalization.id_osa_hospitalizacion) || null, stationId: Number(route.params.id), bedId: Number(selectedBed.value?.id_cama) } })
function openVitals(bed) { vitalsPatient.value = bed.info_paciente }
function openTransfer(bed) { transferBed.value = bed }
async function openBedPlan(bed, type) { selectedBed.value = bed; actionMessage.value = ''; try { if (type === 'medication') await plans.checkMedication(planContext.value); else await plans.checkProcedure(planContext.value); viewerType.value = type } catch (reason) { actionMessageType.value = 'danger'; actionMessage.value = obtenerMensajeError(reason) } }
async function createPlan() { const type = viewerType.value; viewerType.value = null; try { if (type === 'medication') await plans.loadMedicationCatalogs(); else await plans.loadServiceCatalogs(true); editorType.value = type } catch (reason) { actionMessageType.value = 'danger'; actionMessage.value = obtenerMensajeError(reason) } }
function closePlan() { viewerType.value = null; editorType.value = null; selectedBed.value = null }
async function planSaved() { const type = editorType.value; closePlan(); actionMessageType.value = 'success'; actionMessage.value = `Plan de ${type === 'medication' ? 'medicamentos' : 'procedimientos'} creado correctamente.`; await load() }
async function transferSaved() { transferBed.value = null; actionMessageType.value = 'success'; actionMessage.value = 'Solicitud de traslado creada correctamente.'; await load() }
async function load() { loading.value = true; error.value = ''; try { detail.value = await store.loadStationDetail(route.params.id, true) } catch (reason) { error.value = obtenerMensajeError(reason) } finally { loading.value = false } }
onMounted(load)
</script>

<style scoped>
.metric{display:flex;flex-direction:column;padding:1rem 1.25rem;background:var(--bs-body-bg);border:1px solid var(--bs-border-color);border-radius:.75rem}.metric small{color:var(--bs-secondary-color)}.metric strong{font-size:1.5rem}.bedroom{padding:1rem;border:1px solid var(--bs-border-color);border-radius:.75rem}.bed{position:relative;height:100%;padding:1rem;border:1px solid var(--bs-border-color);border-top:3px solid;border-radius:.85rem;background:#fff}.bed.available{border-top-color:var(--bs-success)}.bed.occupied{border-top-color:var(--bs-primary);box-shadow:0 8px 24px rgba(27,82,130,.07)}.bed.unavailable{border-top-color:var(--bs-secondary)}.bed-header{display:flex;justify-content:space-between;gap:.5rem;align-items:center}.bed-header>div{color:#344054}.status{display:flex;align-items:center;gap:.3rem;font-size:.65rem;font-weight:700;text-transform:uppercase}.status i{font-size:.45rem}.occupied .status{color:var(--bs-primary)}.available .status{color:var(--bs-success)}.clinical-alert{display:flex;align-items:center;gap:.4rem;margin-top:.75rem;padding:.55rem .65rem;border-radius:.55rem;background:#fff0f0;color:#c93643;font-size:.72rem}.patient{display:flex;align-items:center;gap:.7rem;margin-top:1rem;padding:0}.patient-avatar{display:grid;place-items:center;width:43px;height:43px;flex:none;border-radius:12px;background:linear-gradient(135deg,#176fac,#32a4dc);color:#fff;font-weight:800}.patient strong,.patient small,.patient span{display:block}.patient small{color:var(--bs-secondary-color);font-size:.7rem}.patient span{color:#337dad;font-size:.7rem;font-weight:600}.stay-summary{display:grid;grid-template-columns:1fr 1fr;gap:.5rem;margin-top:.8rem}.stay-summary>div{padding:.55rem;background:#f6f8fb;border-radius:.55rem}.stay-summary small,.stay-summary strong{display:block}.stay-summary small,.clinical-summary small,.responsible small{font-size:.62rem;color:#8492a5}.stay-summary strong{font-size:.72rem}.clinical-summary{display:grid;gap:.4rem;margin-top:.7rem}.clinical-summary>div,.responsible{display:flex;gap:.5rem;align-items:center;padding:.5rem;border:1px solid #edf0f3;border-radius:.55rem}.clinical-summary i,.responsible>i{color:var(--bs-primary);font-size:1.05rem}.clinical-summary span,.responsible span{min-width:0}.clinical-summary small,.clinical-summary strong,.responsible small,.responsible strong{display:block}.clinical-summary strong,.responsible strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.69rem}.responsible{margin-top:.5rem}.bed-actions{display:flex;gap:.45rem;margin-top:.85rem}.action-menu{position:relative}.action-menu summary{display:grid;place-items:center;height:100%;list-style:none}.action-menu summary::-webkit-details-marker{display:none}.action-menu-list{position:absolute;z-index:20;right:0;bottom:calc(100% + .4rem);width:240px;padding:.4rem;background:#fff;border:1px solid #e1e7ed;border-radius:.7rem;box-shadow:0 14px 36px rgba(24,45,68,.18)}.action-menu-list>span{display:block;padding:.4rem .55rem .2rem;color:#98a2b3;font-size:.58rem;font-weight:800;text-transform:uppercase;letter-spacing:.08em}.action-menu-list a{display:flex;align-items:center;gap:.5rem;padding:.5rem .55rem;border-radius:.45rem;color:#344054;font-size:.75rem}.action-menu-list a:hover{background:#eff6fc;color:var(--bs-primary)}.action-menu-list .external-icon{margin-left:auto;color:#98a2b3;font-size:.7rem}.action-menu-list .danger-action{margin-top:.25rem;border-top:1px solid #f0e1e3;color:#c6404c}.empty-bed{display:flex;flex-direction:column;align-items:center;gap:.35rem;padding:2rem;color:#98a2b3}.empty-bed i{font-size:2rem}.reservation{margin-top:.75rem;color:var(--bs-warning);font-size:.8rem;font-weight:600}
.action-menu-list button{display:flex;align-items:center;gap:.5rem;width:100%;padding:.5rem .55rem;border:0;border-radius:.45rem;background:transparent;color:#344054;font-size:.75rem;text-align:left}.action-menu-list button:hover{background:#eff6fc;color:var(--bs-primary)}
</style>
